"""ShiftSync: minimal shift scheduling for small restaurants.
Staff post availability, managers publish a schedule, swaps are requested in-app
instead of by text, and overtime is flagged before it happens."""
from dataclasses import dataclass, field

OVERTIME_HOURS = 40

@dataclass
class Shift:
    staff: str
    day: str
    hours: float

@dataclass
class Schedule:
    shifts: list = field(default_factory=list)

    def add(self, staff, day, hours):
        self.shifts.append(Shift(staff, day, hours))

    def hours_by_staff(self):
        totals = {}
        for s in self.shifts:
            totals[s.staff] = totals.get(s.staff, 0) + s.hours
        return totals

    def overtime_warnings(self):
        return [f"{n}: {h}h scheduled (over {OVERTIME_HOURS})"
                for n, h in self.hours_by_staff().items() if h > OVERTIME_HOURS]

    def swap(self, staff_a, day_a, staff_b):
        """Swap who works a given day's shift; both must be on the schedule for that day."""
        a = next((s for s in self.shifts if s.staff == staff_a and s.day == day_a), None)
        if a is None:
            raise ValueError("no shift to swap")
        a.staff = staff_b
        return a

@dataclass
class SwapRequest:
    staff: str
    day: str
    offers: list = field(default_factory=list)

    def offer(self, staff_name):
        if staff_name != self.staff and staff_name not in self.offers:
            self.offers.append(staff_name)

    def status_line(self):
        who = ", ".join(self.offers) if self.offers else "no offers yet"
        return f"Swap {self.staff} {self.day}: covers offered by {who}"

def schedule_text(schedule):
    """Plain-text view cooks can open on a phone via SMS or web link (no login)."""
    lines = []
    for s in schedule.shifts:
        lines.append(f"{s.day}: {s.staff} {s.hours}h")
    return "\n".join(lines)

if __name__ == "__main__":
    s = Schedule()
    s.add("Ana", "Mon", 8); s.add("Ana", "Tue", 8); s.add("Ana", "Wed", 8)
    s.add("Ana", "Thu", 8); s.add("Ana", "Fri", 8); s.add("Ana", "Sat", 8)
    s.add("Luis", "Sat", 6)
    print(s.overtime_warnings())
    s.swap("Ana", "Sat", "Luis")
    print(s.hours_by_staff())

    r = SwapRequest("Ana", "Sat")
    r.offer("Luis"); r.offer("Luis")
    print(r.status_line())
    print(schedule_text(s))
